//#region src/providers/provider-models.ts
/**
* Model catalog surface. Re-exports the SDK-sourced generated catalog and
* derives the default model per provider type. The catalog is produced by
* `pnpm generate:model-catalog`; never hand-maintain model lists here.
*/
/**
* Curated default per provider type. The catalog order follows the SDK union
* (oldest first), so no catalog position is a sensible default. A test pins
* each entry to the catalog, so a stale default fails CI instead of silently
* falling back to a preview or alias.
*/
const PREFERRED_DEFAULT_MODELS = {
	anthropic: "claude-sonnet-5",
	openai: "gpt-5-mini",
	google: "gemini-2.5-flash"
};
const getDefaultModel = (type) => PREFERRED_DEFAULT_MODELS[type];
/** True when the provider no longer serves `modelId` (it answers 404). */
const isRetiredModel = (type, modelId) => Object.hasOwn(RETIRED_MODELS[type], modelId);
/** The same-tier successor of a retired model, else undefined. */
const retiredSuccessor = (type, modelId) => isRetiredModel(type, modelId) ? RETIRED_MODELS[type][modelId] : void 0;
/** Successor + retirement date of a deprecated model, else undefined. */
const deprecationOf = (type, modelId) => Object.hasOwn(DEPRECATED_MODELS[type], modelId) ? DEPRECATED_MODELS[type][modelId] : void 0;
/** `modelId`, or its successor when the provider retired it. */
const usableModel = (type, modelId) => retiredSuccessor(type, modelId) ?? modelId;
/**
* The model to call for a provider record: its stored choice, else the type
* default, healed past retirement. The ONE place `provider.model` meets the
* default — a guard bans the raw `.model ?? getDefaultModel(` pattern
* elsewhere, because it skips the healing.
*/
const modelForProvider = (provider) => usableModel(provider.type, provider.model ?? getDefaultModel(provider.type));
//#endregion
//#region src/providers/model-names.ts
const PIN = /^(.+?)-(\d{8}|\d{4}-\d{2}-\d{2}|\d{3,4})$/;
const splitPin = (id) => {
	const m = PIN.exec(id);
	return m ? {
		base: m[1],
		pin: m[2]
	} : { base: id };
};
const formatPin = (pin) => /^\d{8}$/.test(pin) ? `${pin.slice(0, 4)}-${pin.slice(4, 6)}-${pin.slice(6)}` : pin;
const capitalize = (word) => word.charAt(0).toUpperCase() + word.slice(1);
const CLAUDE = /^claude-([a-z]+)-(\d+)(?:-(\d{1,2}))?$/;
const nameOf = (id) => {
	const claude = CLAUDE.exec(id);
	if (claude) {
		const [, family, major, minor] = claude;
		return `Claude ${capitalize(family)} ${minor ? `${major}.${minor}` : major}`;
	}
	if (id.startsWith("gpt-")) {
		const [version, ...rest] = id.slice(4).split("-");
		return [`GPT-${version}`, ...rest].join(" ");
	}
	if (id.startsWith("gemini-")) return id.split("-").map(capitalize).join(" ");
	return id;
};
/**
* A model's product name ("Claude Sonnet 5", "GPT-5 mini"), with a pinned
* snapshot's date or revision in brackets. An id with no known shape (a custom
* or future model) is shown as it is.
*/
const modelDisplayName = (modelId) => {
	const { base, pin } = splitPin(modelId);
	const name = nameOf(base);
	if (!pin || name === base) return nameOf(modelId);
	return `${name} (${formatPin(pin)})`;
};
/**
* The catalog models worth offering: a pinned snapshot is dropped when its
* alias is listed too. The alias points at a current snapshot of the same
* model line, so offering both would show two entries for one choice; an
* exact snapshot can still be entered through "Other…".
*/
const listedModels = (type) => {
	const ids = MODEL_CATALOG[type].map((m) => m.id);
	return ids.filter((id) => {
		const { base, pin } = splitPin(id);
		return !pin || !ids.includes(base);
	});
};
//#endregion
//#region src/providers/read-provider-error.ts
const MAX_DEPTH = 4;
const str = (v) => typeof v === "string" ? v : void 0;
const readBody = (body) => {
	if (typeof body !== "string") return {};
	try {
		const e = JSON.parse(body)?.error;
		if (typeof e !== "object" || e === null) return {};
		return {
			errorType: str(e.type),
			errorCode: str(e.code),
			errorStatus: str(e.status),
			errorMessage: str(e.message)
		};
	} catch {
		return {};
	}
};
const isEmpty = (info) => Object.values(info).every((v) => v === void 0);
const readProviderError = (error, depth = 0) => {
	if (typeof error !== "object" || error === null || depth > MAX_DEPTH) return {};
	const e = error;
	const ownType = str(e.type)?.endsWith("_error") ? str(e.type) : void 0;
	const body = readBody(e.responseBody);
	const info = {
		statusCode: typeof e.statusCode === "number" ? e.statusCode : void 0,
		...body,
		errorType: body.errorType ?? ownType
	};
	if (!isEmpty(info)) return info;
	return readProviderError(e.lastError ?? e.cause, depth + 1);
};
//#endregion
//#region src/providers/model-not-found.ts
/**
* Detects a provider rejecting the requested model as unknown (retired or
* misspelled). A 404 alone is not enough: the provider must name a model.
* Structured fields win, read through the shared `readProviderError` (the
* only cause/lastError walker):
* Anthropic `not_found_error` whose message names a model, OpenAI
* `model_not_found`, Google `NOT_FOUND` on a `models/...` path. Only when no
* structured field exists does the top-level message decide ("The model `x`
* does not exist", "models/x is not found").
*/
const MODEL_WORD = /\bmodel\b/i;
const MODEL_PATH = /\bmodels\//;
const MISSING_MODEL_TEXT = /\bthe model `[^`]+` does not exist|\bmodels\/[\w.-]+ is not found|model_not_found/i;
/** True when the structured fields say the requested model does not exist. */
const namesMissingModel = (info) => {
	const message = info.errorMessage ?? "";
	if (info.errorType === "not_found_error") return MODEL_WORD.test(message);
	if (info.errorCode === "model_not_found") return true;
	if (info.errorStatus === "NOT_FOUND") return MODEL_PATH.test(message);
	return false;
};
const messageOf = (error) => {
	if (typeof error !== "object" || error === null) return "";
	const message = error.message;
	return typeof message === "string" ? message : "";
};
const isModelNotFoundError = (error) => {
	const info = readProviderError(error);
	if (namesMissingModel(info)) return true;
	if (info.errorType || info.errorCode || info.errorStatus) return false;
	return MISSING_MODEL_TEXT.test(messageOf(error));
};
//#endregion
//#region src/providers/resolve-model-for-purpose.ts
/**
* Resolves the provider + model for an AI purpose: the purpose's own binding,
* else the `default` binding, else the default provider paired with its stored
* model (transitional back-compat) or the catalog's default model, else null.
* A binding whose provider no longer exists is skipped; a binding that stored
* a blank model keeps its provider and runs that provider's model (healing
* rows written before blank models were rejected), and a model the
* provider has retired resolves to its same-tier successor instead of a
* certain 404. The single resolution
* path shared by chat, generation, coaching, and batch. Generic over the
* concrete provider record so callers keep their full provider type.
*/
const fromBinding = (binding, providers) => {
	if (!binding) return void 0;
	const provider = providers.find((p) => p.id === binding.providerId);
	if (!provider) return void 0;
	return {
		provider,
		modelId: binding.modelId.trim() ? usableModel(provider.type, binding.modelId) : modelForProvider(provider)
	};
};
const fromDefaultProvider = (providers) => {
	const provider = providers.find((p) => p.isDefault) ?? providers[0];
	if (!provider) return void 0;
	return {
		provider,
		modelId: modelForProvider(provider)
	};
};
const resolveModelForPurpose = (purpose, providers, bindings) => {
	const override = bindings.find((b) => b.purpose === purpose);
	const fallback = bindings.find((b) => b.purpose === "default");
	return fromBinding(override, providers) ?? fromBinding(fallback, providers) ?? fromDefaultProvider(providers) ?? null;
};
